ragraph", "content": [{"type": "text", "text": "忘记检验"}]}]}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#eff6ff", "borderColor": "#3b82f6", "icon": "📊"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "刷题建议：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "一元一次方程是最基础的方程。解法简单但要细心，注意移项变号。"}]}]}]}$$ AS jsonb), NULL, '数量关系-方程与不定方程-一元一次方程的核心知识点和解题方法。', category_node.id, CAST('["数量关系", "方程与不定方程", "一元一次方程"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_eq_linear", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
